import React,{useState,useRef} from 'react';import{createRoot}from'react-dom/client';import ChartFullscreen from '../../src/ChartFullscreen.jsx';function Chart(){const[n,setN]=useState(0),[selected,setSelected]=useState(false);return <ChartFullscreen><button onClick={()=>setN(n+1)}>Ponto {n}</button><svg tabIndex="0" viewBox="0 0 500 200" role="img" aria-label={selected?'Seleção ativa':'Sem seleção'} onClick={()=>setSelected(true)} onKeyDown={e=>{if(e.key==='Escape'&&selected){e.preventDefault();e.stopPropagation();setSelected(false)}}}><path d="M0 100 L500 0" stroke="black"/></svg><p>{selected?'Seleção ativa':'Sem seleção'}</p><iframe title="Frame de teste" srcDoc='<button>Botão do iframe</button>'/><button onClick={()=>window.location.hash='outra'}>Mudar rota</button></ChartFullscreen>}function Test(){const d=useRef();return <><button onClick={()=>d.current.showModal()}>Abrir modal pai</button><button id="fundo">Botão de fundo</button><Chart/><dialog ref={d}><h2>Modal pai</h2><Chart/><button onClick={()=>d.current.close()}>Fechar pai</button></dialog></>}createRoot(document.getElementById('root')).render(<Test/>);
